Rtring_trigger(CLK := g_bUserDefineControlOutputM OR bUserDefineControlHMI);
IF Rtring_trigger.Q THEN
  g_bUserDefineControlOutputM := FALSE;
  bUserDefineControlHMI := FALSE;
  g_bInterferenceProtectionDetection := TRUE;
END_IF;
Rtring_triggerForHMI(CLK := bHMIExecuteOutput);
IF Rtring_triggerForHMI.Q THEN
  bHMIExecuteOutput := FALSE;
  g_bInterferenceProtectionDetection := FALSE;
  nOutputState := 50;
  IF g_dUserDefineControlOutputIndexM = 100.0 THEN(*关闭所有输出口*)
    nOutputState := 500;
    bTempFlag := FALSE;
  END_IF;
END_IF;



CASE nOutputState OF 
  0:
    nOutputState := 0;
  50:
    IF g_dUserDefineControlOutputEnableM = 1.0 THEN(*打开输出口*)
      bTempFlag := TRUE;
    ELSE
      bTempFlag := FALSE;
    END_IF;   
    nOutputState := 60;
  60:
