      nDefineOutPutIndex := LREAL_TO_INT(g_dUserDefineControlOutputIndexM);
      nOutPutIndex := LREAL_TO_INT(g_dUserDefineControlOutputIndexM);
    ELSIF g_dUserDefineControlOutputEnableTypeM = 1.0 THEN
      nDefineOutPutIndex := LREAL_TO_INT(g_dUserDefineControlOutputIndexM) + 16;
      nOutPutIndex := LREAL_TO_INT(g_dUserDefineControlOutputIndexM) + 16;
    ELSIF g_dUserDefineControlOutputEnableTypeM = 2.0 THEN
      nDefineOutPutIndex := LREAL_TO_INT(g_dUserDefineControlOutputIndexM) + 32;
      nOutPutIndex := LREAL_TO_INT(g_dUserDefineControlOutputIndexM) + 32;
    ELSIF g_dUserDefineControlOutputEnableTypeM = 3.0 THEN
      nDefineOutPutIndex := LREAL_TO_INT(g_dUserDefineControlOutputIndexM) + 48;
